package id.saryu.libcore;

import org.jetbrains.annotations.NotNull;

import java.io.InputStream;
import java.util.Properties;

/**
 * Build metadata generated by Gradle ({@code build-info.properties}). Each plugin
 * jar contains its own copy, so the anchor class must be loaded from that jar.
 */
public final class BuildInfo {

    private final String version;
    private final String commit;
    private final String channel;

    private BuildInfo(@NotNull String version, @NotNull String commit, @NotNull String channel) {
        this.version = version;
        this.commit = commit;
        this.channel = channel;
    }

    public static @NotNull BuildInfo load(@NotNull Class<?> anchor, @NotNull String fallbackVersion) {
        Properties properties = new Properties();
        try (InputStream in = anchor.getResourceAsStream("/build-info.properties")) {
            if (in != null) properties.load(in);
        } catch (Exception ignored) {
            // Fall back to plugin.yml below; build metadata is informational only.
        }
        String version = value(properties, "version", fallbackVersion);
        String commit = value(properties, "commit", "unknown");
        String channel = value(properties, "channel", "dev");
        return new BuildInfo(version, commit, channel);
    }

    private static @NotNull String value(@NotNull Properties properties, @NotNull String key,
                                         @NotNull String fallback) {
        String value = properties.getProperty(key);
        return value == null || value.isBlank() ? fallback : value;
    }

    public @NotNull String getVersion() {
        return version;
    }

    public @NotNull String getCommit() {
        return commit;
    }

    public @NotNull String getChannel() {
        return channel;
    }

    /** Example: {@code 3.0.2-dev+abc1234 (dev, commit abc1234)}. */
    public @NotNull String display() {
        return version + " (" + channel + ", commit " + commit + ")";
    }
}
